-- Stage 3 reference-only sync. No bootstrap/backfill and no trust promotion.
-- Generated by scripts/generate-sync-migrations.py; apply independently per project.
begin;
do $$ begin if not exists(select 1 from pg_roles where rolname='tl_auto_power_sync') then
 create role tl_auto_power_sync nologin nosuperuser nocreatedb nocreaterole nobypassrls noinherit;
end if;
if exists(select 1 from pg_roles where rolname='tl_auto_power_sync' and (rolsuper or rolbypassrls or rolcreatedb or rolcreaterole or rolcanlogin)) then raise exception 'sync role must be restricted NOLOGIN'; end if;
end $$;
alter table public.vehicle_power_specs add column sync_origin jsonb;
alter table public.vehicle_power_specs add column sync_record jsonb;
create unique index vehicle_power_sync_origin_unique on public.vehicle_power_specs ((sync_origin->>'project'),(sync_origin->>'recordId')) where sync_origin is not null;
create table public.vehicle_power_sync_state (
 record_id text primary key, entity text not null, revision bigint not null check(revision>0), signature text not null,
 raw jsonb not null, retired boolean not null default false, updated_at timestamptz not null default now()
);
create index on public.vehicle_power_sync_state(entity);
create table public.vehicle_power_sync_outbox (
 seq bigint generated always as identity primary key, record_id text not null, revision bigint not null,
 operation text not null check(operation in ('upsert','retire','revoke')), raw jsonb not null,
 event jsonb, state text not null default 'pending' check(state in ('pending','sending','delivered','dead')),
 attempts integer not null default 0, next_at timestamptz not null default now(), lease_until timestamptz,
 error_code text, created_at timestamptz not null default now(), unique(record_id,revision)
);
create index on public.vehicle_power_sync_outbox(next_at,seq) where state in ('pending','sending');
create table public.vehicle_power_sync_inbox (
 event_id text primary key, origin text not null check(origin in ('vehicle-power','tl-auto')), record_id text not null,
 revision bigint not null check(revision>0), fingerprint text not null, raw_event jsonb not null,
 state text not null check(state in ('review','conflict','stale','retired','revoked')), reason text not null,
 received_at timestamptz not null default now(), unique(origin,record_id,revision)
);
create index on public.vehicle_power_sync_inbox(state,received_at);
create table public.vehicle_power_sync_heads (
 origin text not null, record_id text not null, revision bigint not null, fingerprint text not null,
 record jsonb not null, primary key(origin,record_id)
);
create index on public.vehicle_power_sync_heads(fingerprint);
create table public.vehicle_power_sync_checkpoint (
 name text primary key, value text not null, updated_at timestamptz not null default now()
);
create view public.vehicle_power_sync_native as
 select 'spec:'||s.id as entity,'spec:'||s.id||':'||m.id as record_id,
 jsonb_build_object('spec',to_jsonb(s)-'sync_origin'-'sync_record','evidence',to_jsonb(e),'match',to_jsonb(m)) as raw
 from public.vehicle_power_specs s join public.vehicle_power_evidence e on e.id=s.evidence_id join public.vehicle_power_spec_matches m on m.spec_id=s.id where s.sync_origin is null
 union all select 'auto:'||a.id,'auto:'||a.id,jsonb_build_object('automatic',to_jsonb(a)) from public.vehicle_power_automatic_reference a;
create function public.vehicle_power_sync_refresh(target text) returns void language plpgsql security definer set search_path=pg_catalog as $$
declare n record; old public.vehicle_power_sync_state%rowtype; sig text; op text; rev bigint;
begin
 perform pg_advisory_xact_lock(71032003);
 for n in select * from public.vehicle_power_sync_native where entity=target order by record_id loop
  sig:=md5(n.raw::text);
  select * into old from public.vehicle_power_sync_state where record_id=n.record_id for update;
  if found and old.signature=sig and not old.retired then continue; end if;
  rev:=coalesce(old.revision,0)+1;
  op:=case when coalesce(n.raw->'spec'->>'status',n.raw->'automatic'->>'status')='retired' then 'retire'
    when coalesce(n.raw->'evidence'->>'status',n.raw->'evidence'->>'review_status') in ('rejected','revoked') or n.raw->'spec'->>'status'='rejected' then 'revoke' else 'upsert' end;
  insert into public.vehicle_power_sync_state(record_id,entity,revision,signature,raw,retired) values(n.record_id,target,rev,sig,n.raw,false)
   on conflict(record_id) do update set revision=excluded.revision,signature=excluded.signature,raw=excluded.raw,retired=false,updated_at=now();
  insert into public.vehicle_power_sync_outbox(record_id,revision,operation,raw) values(n.record_id,rev,op,n.raw);
 end loop;
 for old in select * from public.vehicle_power_sync_state st where st.entity=target and not st.retired and not exists(select 1 from public.vehicle_power_sync_native existing_native where existing_native.record_id=st.record_id) for update loop
  update public.vehicle_power_sync_state set revision=revision+1,retired=true,updated_at=now() where record_id=old.record_id;
  insert into public.vehicle_power_sync_outbox(record_id,revision,operation,raw) values(old.record_id,old.revision+1,'retire',old.raw);
 end loop;
end $$;
create function public.vehicle_power_sync_capture() returns trigger language plpgsql security definer set search_path=pg_catalog as $$
declare r jsonb; id text; s record;
begin
 r:=case when tg_op='DELETE' then to_jsonb(old) else to_jsonb(new) end;
 if tg_table_name in ('specifications','vehicle_power_specs') then
  if r->'sync_origin' is not null and r->'sync_origin'<>'null'::jsonb then return null; end if;
  perform public.vehicle_power_sync_refresh('spec:'||(r->>'id'));
 elsif tg_table_name='vehicle_power_spec_matches' then
  if tg_op<>'INSERT' then perform public.vehicle_power_sync_refresh('spec:'||old.spec_id); end if;
  if tg_op<>'DELETE' then perform public.vehicle_power_sync_refresh('spec:'||new.spec_id); end if;
 elsif tg_table_name='vehicle_power_automatic_reference' then perform public.vehicle_power_sync_refresh('auto:'||(r->>'id'));
 else
  for s in select sp.id from public.vehicle_power_specs sp where sp.evidence_id=(r->>'id')::uuid and sp.sync_origin is null loop
   perform public.vehicle_power_sync_refresh('spec:'||s.id);
  end loop;
 end if;
 return null;
end $$;
create trigger vehicle_power_sync_capture_spec after insert or update or delete on public.vehicle_power_specs for each row execute function public.vehicle_power_sync_capture();
create trigger vehicle_power_sync_capture_evidence after insert or update or delete on public.vehicle_power_evidence for each row execute function public.vehicle_power_sync_capture();
create trigger vehicle_power_sync_capture_match after insert or update or delete on public.vehicle_power_spec_matches for each row execute function public.vehicle_power_sync_capture();
create trigger vehicle_power_sync_capture_automatic after insert or update or delete on public.vehicle_power_automatic_reference for each row execute function public.vehicle_power_sync_capture();
-- Bounded reconciliation includes removed native entities and returns a stable lexicographic cursor.
create function public.vehicle_power_sync_reconcile(after_key text default '', batch_size integer default 100) returns text language plpgsql security definer set search_path=pg_catalog as $$
declare r record; last_key text;
begin
 if batch_size<1 or batch_size>200 then raise exception 'invalid_batch_size'; end if;
 for r in select entity from (select entity from public.vehicle_power_sync_native union select entity from public.vehicle_power_sync_state) u where entity>after_key order by entity limit batch_size loop
 perform public.vehicle_power_sync_refresh(r.entity);last_key:=r.entity;
 end loop;
 return last_key;
end $$;
-- Imports cannot modify a native row. Existing resolver only reads approved/provisional;
-- imported rows stay quarantined (VP rejected + review metadata / TL draft).
create function public.vehicle_power_sync_apply(r jsonb, tombstone boolean) returns uuid language plpgsql security definer set search_path=pg_catalog as $$
declare sid uuid; eid uuid; c numeric; ep numeric; calc numeric; prop text; basis text; peer text;
begin
 peer:=r->'origin'->>'project';
 if peer<>'vehicle-power' or length(r::text)>262144 or r->>'contractVersion'<>'power-record-v1' then raise exception 'invalid_sync_record'; end if;
 perform pg_advisory_xact_lock(71032004);
 select id into sid from public.vehicle_power_specs where sync_origin->>'project'=peer and sync_origin->>'recordId'=r->'origin'->>'recordId' for update;
 if tombstone then
  if sid is not null then update public.vehicle_power_specs set status='retired',sync_origin=r->'origin',sync_record=r where id=sid and sync_origin is not null; end if;
  return sid;
 end if;
 if sid is not null and exists(select 1 from public.vehicle_power_specs where id=sid and status='approved') then return sid; end if;
 select (x->>'kw')::numeric into c from jsonb_array_elements(r->'measurements') x where x->>'basis'='combustion_rated' limit 1;
 select (x->>'kw')::numeric into ep from jsonb_array_elements(r->'measurements') x where x->>'basis'='electric_30min' limit 1;
 prop:=r->>'propulsion';
 -- No invented topology or component sum; unsupported/incomplete data stays in immutable inbox review.
 if prop='hybrid_phev' then return null; end if;
 calc:=case when prop='ice' then c when prop in ('electric','hybrid_sequential') then ep when prop='hybrid_parallel' then c+ep end;
 if calc is null then return null; end if;
 if sid is null then
  insert into public.vehicle_power_evidence(source_kind,source_uri,propulsion_type,dvs_power_kw,electric_power_kw_30min,review_status,review_note)
   values('manual','urn:power-sync:'||peer,prop,c,ep,'draft','Imported reference: review required') returning id into eid;
  insert into public.vehicle_power_specs(spec_key,version,status,vehicle_category,propulsion_type,dvs_power_kw,electric_power_kw_30min,calculation_power_kw,evidence_id,sync_origin,sync_record)
   values('sync:'||peer||':'||md5(r->'origin'->>'recordId'),1,'draft','M1',prop,c,ep,calc,eid,r->'origin',r) returning id into sid;
 else
  update public.vehicle_power_specs set status='draft',propulsion_type=prop,dvs_power_kw=c,electric_power_kw_30min=ep,calculation_power_kw=calc,sync_origin=r->'origin',sync_record=r where id=sid;
  update public.vehicle_power_evidence set propulsion_type=prop,dvs_power_kw=c,electric_power_kw_30min=ep where id=(select evidence_id from public.vehicle_power_specs where id=sid);
 end if;
 delete from public.vehicle_power_spec_matches where spec_id=sid;
 insert into public.vehicle_power_spec_matches(spec_id,brand,model,generation,trim,model_code,engine_code,fuel_type,production_year_from,production_year_to,engine_cc_from,engine_cc_to,drive_type)
 values(sid,r->'vehicle'->>'brand',r->'vehicle'->>'model',r->'vehicle'->>'generation',r->'vehicle'->>'trim',r->'vehicle'->>'modelCode',r->'vehicle'->>'engineCode',r->'vehicle'->>'fuelType',(r->'vehicle'->>'yearFrom')::integer,(r->'vehicle'->>'yearTo')::integer,coalesce((r->'vehicle'->>'engineCcFrom')::integer,(r->'vehicle'->>'engineCc')::integer),coalesce((r->'vehicle'->>'engineCcTo')::integer,(r->'vehicle'->>'engineCc')::integer),r->'vehicle'->>'driveType');
 return sid;
end $$;
